function escHtml(value){return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"})[ch]);}
function langFor(panel){const preferred=String(panel?._preferredLang||"").toLowerCase();const raw=(preferred&&preferred!=="auto")?preferred:String(panel?._lang||panel?._haLang||"en").toLowerCase();const base=raw.split("-")[0];return TEXT[raw]?raw:(TEXT[base]?base:"en");}
function text(panel){return TEXT[langFor(panel)]||TEXT.en;}
function plain(panel){const lang=langFor(panel);return PLAIN[lang]||PLAIN.en;}
function help(panel,key){const lang=langFor(panel);return (HELP[lang]&&HELP[lang][key])||HELP.en[key]||"";}
function localized(group,key,panel){const lang=langFor(panel);return group?.[key]?.[lang]||group?.[key]?.en||String(key||"");}
function signalText(panel,value){const raw=String(value||"");const lang=langFor(panel);return SIGNAL[lang]?.[raw]||SIGNAL.en[raw]||raw.replaceAll("_"," ").replace(/^./,m=>m.toUpperCase());}
function signalHelp(panel,value){const raw=String(value||"");const lang=langFor(panel);return SIGNAL_HELP[lang]?.[raw]||SIGNAL_HELP.en[raw]||help(panel,raw)||"";}
function helpBubble(panel,key){const body=help(panel,key);if(!body)return "";return `<span class="field-help" role="tooltip">${escHtml(body)}</span>`;}
function signalHelpBubble(panel,key){const body=signalHelp(panel,key);if(!body)return "";return `<span class="field-help" role="tooltip">${escHtml(body)}</span>`;}
const WHOLE_UNIT_CATEGORIES=["etf","stock","fund","crypto","commodity","fx","index","other"];
const HELP_PORTAL_ID="ha-investment-help-portal";
const HELP_PORTAL_STYLE_ID="ha-investment-help-portal-style";
function ensureHelpPortal(){
  let style=document.getElementById(HELP_PORTAL_STYLE_ID);
  if(!style){style=document.createElement("style");style.id=HELP_PORTAL_STYLE_ID;style.textContent=`#${HELP_PORTAL_ID}{position:fixed;z-index:2147483000;box-sizing:border-box;padding:11px 12px;border:1px solid var(--divider-color,#777);border-radius:11px;background:var(--card-background-color,#fff);box-shadow:0 10px 30px rgba(0,0,0,.34);color:var(--primary-text-color,#111);font-size:12px;line-height:1.5;font-weight:400;white-space:normal;overflow-wrap:anywhere;word-break:normal;pointer-events:auto}#${HELP_PORTAL_ID}[hidden]{display:none!important}#${HELP_PORTAL_ID}[data-mode="desktop"]{width:min(360px,calc(100vw - 24px));max-width:calc(100vw - 24px);transform:none}#${HELP_PORTAL_ID}[data-mode="touch"]{left:50%!important;right:auto!important;top:auto!important;bottom:calc(16px + env(safe-area-inset-bottom,0px))!important;transform:translateX(-50%)!important;width:min(520px,calc(100vw - 32px));max-width:calc(100vw - 32px);cursor:pointer;touch-action:manipulation}`;document.head.appendChild(style);}
  let portal=document.getElementById(HELP_PORTAL_ID);
  if(!portal){portal=document.createElement("div");portal.id=HELP_PORTAL_ID;portal.setAttribute("role","tooltip");portal.hidden=true;document.body.appendChild(portal);}
  return portal;
}
function helpTextForTarget(target){const own=target?.querySelector?.(":scope > .field-help");const next=target?.nextElementSibling?.matches?.(".field-help")?target.nextElementSibling:null;return String((own||next)?.textContent||"").trim();}
function positionHelpPortal(portal,target,touch){
  if(touch){portal.dataset.mode="touch";portal.style.left="50%";portal.style.right="auto";portal.style.top="auto";portal.style.bottom="calc(16px + env(safe-area-inset-bottom,0px))";portal.style.transform="translateX(-50%)";return;}
  portal.dataset.mode="desktop";portal.style.transform="none";portal.style.bottom="auto";portal.style.left="12px";portal.style.top="12px";
  const rect=target.getBoundingClientRect();const box=portal.getBoundingClientRect();const margin=12;const gap=8;
  let left=Math.max(margin,Math.min(rect.left,window.innerWidth-box.width-margin));
  let top=rect.bottom+gap;if(top+box.height>window.innerHeight-margin)top=Math.max(margin,rect.top-box.height-gap);
  portal.style.left=`${Math.round(left)}px`;portal.style.top=`${Math.round(top)}px`;
}
function wholeUnitSummary(panel,categories){const selected=WHOLE_UNIT_CATEGORIES.filter(category=>(categories||[]).includes(category));const t=text(panel);if(!selected.length)return t.wholeUnitNone||TEXT.en.wholeUnitNone;if(selected.length===WHOLE_UNIT_CATEGORIES.length)return t.wholeUnitAll||TEXT.en.wholeUnitAll;return selected.map(category=>panel.catName(category)).join(", ");}
function wholeUnitMultiHtml(panel,draft){const selected=new Set(Array.isArray(draft.wholeUnitCategories)?draft.wholeUnitCategories:[]);const t=text(panel);return `<div class="setting-field whole-unit-multi"><span class="help-label" tabindex="0">${escHtml(t.wholeUnitTypes||panel.t("wholeUnitsOnly"))}${helpBubble(panel,"wholeUnits")}</span><details class="multi-select" data-whole-unit-multi><summary>${escHtml(wholeUnitSummary(panel,[...selected]))}</summary><div class="multi-select-options">${WHOLE_UNIT_CATEGORIES.map(category=>`<label><input name="indication_whole_unit_category" type="checkbox" value="${category}" ${selected.has(category)?"checked":""}/><span>${escHtml(panel.catName(category))}</span></label>`).join("")}</div></details></div>`;}
