function markdownHtml(value){const lines=String(value??"").replace(/\r/g,"").split("\n");let out="",list=null,para=[];const flushPara=()=>{if(para.length){out+=`<p>${inlineMd(para.join(" "))}</p>`;para=[];}};const closeList=()=>{if(list){out+=`</${list}>`;list=null;}};for(let i=0;i<lines.length;i++){const line=lines[i];if(/^```/.test(line)){flushPara();closeList();let code=[];i++;while(i<lines.length&&!/^```/.test(lines[i])){code.push(lines[i]);i++;}out+=`<pre><code>${escHtml(code.join("\n"))}</code></pre>`;continue;}const h=line.match(/^(#{1,4})\s+(.+)$/);if(h){flushPara();closeList();out+=`<h${h[1].length}>${inlineMd(h[2])}</h${h[1].length}>`;continue;}const ul=line.match(/^\s*[-*]\s+(.+)$/);if(ul){flushPara();if(list!=="ul"){closeList();out+="<ul>";list="ul";}out+=`<li>${inlineMd(ul[1])}</li>`;continue;}const ol=line.match(/^\s*\d+[.)]\s+(.+)$/);if(ol){flushPara();if(list!=="ol"){closeList();out+="<ol>";list="ol";}out+=`<li>${inlineMd(ol[1])}</li>`;continue;}if(!line.trim()){flushPara();closeList();continue;}para.push(line.trim());}flushPara();closeList();return out;}
