function fitFor(panel,item,result){const amount=panel.indicationAdjustedSuggestion(item,result)?.amount;const eligible=!!item.allocation_eligible;const riskOk=item.metrics?.risk_history_eligible!==false;if(Number(amount||0)>0&&eligible&&riskOk)return {kind:"good",text:text(panel).goodFit};if(eligible&&riskOk)return {kind:"limited",text:text(panel).limitedFit};return {kind:"none",text:text(panel).notAllocated};}
